sql.where:
AND DELETED = 0

    AND CHANGE_TYPE = #{changeType}


    AND CHANGE_REASON = #{changeReason}


    AND APPROVAL_STATUS = #{approvalStatus}


    AND WARNING_LEVEL = #{warningLevel}


    AND ASSET_ID = #{assetId}


    AND ENTERPRISE_ID = #{enterpriseId}


    AND TRANSFEROR = #{transferor}


    AND TRANSFEREE = #{transferee}


    AND CHANGE_OPERATOR = #{changeOperator}


    AND IS_MAJOR_CHANGE = #{isMajorChange}


    AND NEED_WARNING = #{needWarning}


    AND CHANGE_AMOUNT >= #{minChangeAmount}


    AND CHANGE_AMOUNT <= #{maxChangeAmount}


    AND TRANSFER_PRICE >= #{minTransferPrice}


    AND TRANSFER_PRICE <= #{maxTransferPrice}


    AND DISPOSAL_PRICE >= #{minDisposalPrice}


    AND DISPOSAL_PRICE <= #{maxDisposalPrice}


    AND CHANGE_DATE >= #{startDate}


    AND CHANGE_DATE <= #{endDate}


    AND ASSET_NAME LIKE CONCAT('%', #{assetName}, '%')


    AND CHANGE_DESCRIPTION LIKE CONCAT('%', #{changeDescription}, '%')

mapper.select:
SELECT * FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 ORDER BY CHANGE_DATE DESC, CREATE_TIME DESC
LIMIT #{limit}
FETCH NEXT #{limit} ROWS ONLY

SELECT CHANGE_TYPE as changeType, COUNT(*) as changeCount, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount, TRANSFEROR as transferor, TRANSFEREE as transferee FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY CHANGE_TYPE, TRANSFEROR, TRANSFEREE ORDER BY totalAmount DESC

SELECT CHANGE_TYPE as changeType, APPROVAL_STATUS as approvalStatus, COUNT(*) as changeCount, SUM(CASE WHEN COMPLIANCE_CHECK_RESULT = 'COMPLIANT' THEN 1 ELSE 0 END) as compliantCount, SUM(CASE WHEN COMPLIANCE_CHECK_RESULT = 'NON_COMPLIANT' THEN 1 ELSE 0 END) as nonCompliantCount FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY CHANGE_TYPE, APPROVAL_STATUS ORDER BY changeCount DESC

SELECT WARNING_LEVEL as warningLevel, COUNT(*) as changeCount, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 AND NEED_WARNING = 1
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY WARNING_LEVEL ORDER BY CASE WARNING_LEVEL WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END

SELECT DISPOSAL_METHOD as disposalMethod, COUNT(*) as disposalCount, SUM(DISPOSAL_PRICE) as totalDisposalPrice, SUM(BEFORE_VALUE) as totalBeforeValue, SUM(DISPOSAL_PRICE - BEFORE_VALUE) as totalBenefit, AVG(DISPOSAL_PRICE - BEFORE_VALUE) as avgBenefit FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 AND CHANGE_TYPE = 'DISPOSAL' AND DISPOSAL_PRICE IS NOT NULL AND BEFORE_VALUE IS NOT NULL
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY DISPOSAL_METHOD ORDER BY totalBenefit DESC

SELECT TRANSFEROR as transferor, TRANSFEREE as transferee, TRANSFER_METHOD as transferMethod, COUNT(*) as transferCount, SUM(TRANSFER_PRICE) as totalTransferPrice, AVG(TRANSFER_PRICE) as avgTransferPrice FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 AND CHANGE_TYPE = 'TRANSFER'
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY TRANSFEROR, TRANSFEREE, TRANSFER_METHOD ORDER BY totalTransferPrice DESC

SELECT COUNT(*) as revaluationCount, SUM(AFTER_VALUE - BEFORE_VALUE) as totalValueChange, AVG(AFTER_VALUE - BEFORE_VALUE) as avgValueChange, SUM(CASE WHEN AFTER_VALUE > BEFORE_VALUE THEN 1 ELSE 0 END) as increaseCount, SUM(CASE WHEN AFTER_VALUE < BEFORE_VALUE THEN 1 ELSE 0 END) as decreaseCount FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 AND CHANGE_TYPE = 'REVALUATION' AND BEFORE_VALUE IS NOT NULL AND AFTER_VALUE IS NOT NULL
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}

SELECT COUNT(*) as impairmentCount, SUM(CHANGE_AMOUNT) as totalImpairmentAmount, AVG(CHANGE_AMOUNT) as avgImpairmentAmount, SUM(BEFORE_VALUE) as totalBeforeValue, SUM(AFTER_VALUE) as totalAfterValue FROM ASSET_CHANGE_RECORD WHERE ENTERPRISE_ID = #{enterpriseId} AND DELETED = 0 AND CHANGE_TYPE = 'IMPAIRMENT'
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}

SELECT CHANGE_TYPE as changeType, COUNT(*) as changeCount, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM ASSET_CHANGE_RECORD WHERE DELETED = 0
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY CHANGE_TYPE ORDER BY changeCount DESC

SELECT CHANGE_REASON as changeReason, COUNT(*) as changeCount, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM ASSET_CHANGE_RECORD WHERE DELETED = 0
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY CHANGE_REASON ORDER BY changeCount DESC

SELECT APPROVAL_STATUS as approvalStatus, COUNT(*) as changeCount, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM ASSET_CHANGE_RECORD WHERE DELETED = 0
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY APPROVAL_STATUS ORDER BY changeCount DESC

SELECT WARNING_LEVEL as warningLevel, COUNT(*) as changeCount, SUM(CHANGE_AMOUNT) as totalAmount, AVG(CHANGE_AMOUNT) as avgAmount FROM ASSET_CHANGE_RECORD WHERE DELETED = 0 AND NEED_WARNING = 1
AND CHANGE_DATE >= #{startDate}
AND CHANGE_DATE <= #{endDate}
GROUP BY WARNING_LEVEL ORDER BY CASE WARNING_LEVEL WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END

mapper.delete:
DELETE FROM ASSET_CHANGE_RECORD WHERE DELETED = 1 AND UPDATE_TIME <
DATE_SUB(NOW(), INTERVAL #{days} DAY)
SYSDATE - #{days}
